class VendingMachine:
    def __init__(self):
        self._inventory = {}
        self._balance = 0

    @property
    def inventory(self):
        return dict(self._inventory)

    @inventory.setter
    def inventory(self, inventory):
        self._inventory = dict(inventory)

    @property
    def balance(self):
        return self._balance

    @balance.setter
    def balance(self, balance):
        self._balance = balance

    def add_item(self, item_name, price, quantity):
        if not self.restock_item(item_name, quantity):
            self._inventory[item_name] = {'price': price, 'quantity': quantity}

    def insert_coin(self, amount):
        self._balance += amount
        return self._balance

    def purchase_item(self, item_name):
        if not self.is_valid_purchase(item_name):
            return
        self.execute_purchase(item_name)

    def is_valid_purchase(self, item_name):
        if item_name not in self._inventory:
            return
        item = self._inventory[item_name]
        return item['quantity'] > 0 and self._balance >= item['price']

    def execute_purchase(self, item_name):
        item = self._inventory[item_name]
        self._balance -= item['price']
        item['quantity'] -= 1

    def restock_item(self, item_name, quantity):
        if item_name in self._inventory:
            self._inventory[item_name]['quantity'] += quantity
            return True
        return False

    def display_items(self):
        if not self._inventory:
            return ""
        items = [
            f"{item_name} - ${item_info['price']} [{item_info['quantity']}]"
            for item_name, item_info in self._inventory.items()
        ]
        return "\n".join(items)
